package org.example.controller;

import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.stage.Stage;
import org.example.model.Product;
import org.example.service.ProductService;

import java.io.IOException;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

public class CRUDProductController {
     @FXML
     private TableView<Product> productTable;
     @FXML
     private TextField nameField, priceField, stockField, teamIdField, skuField;
     @FXML
     private TextArea descriptionField;
     @FXML
     private CheckBox activeCheckBox;

    private ProductService productService;
    private ObservableList<Product> productList;
    private Product selectedProduct;

    @FXML
    public void initialize() {
        productService = new ProductService();
        loadProducts();

        // Ajouter un listener pour sélection du tableau
        productTable.getSelectionModel().selectedItemProperty().addListener((obs, oldVal, newVal) -> {
            if (newVal != null) {
                loadProductToForm(newVal);
            }
        });
    }

    private void loadProducts() {
        try {
            List<Product> products = productService.getAll();
            productList = FXCollections.observableArrayList(products);
            productTable.setItems(productList);
        } catch (SQLException e) {
            showAlert("Erreur", "Impossible de charger les produits: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    @FXML
    private void addProduct() {
        if (!validateForm()) return;

        try {
            Product product = createProductFromForm();
            if (productService.add(product)) {
                showAlert("Succès", "Produit ajouté avec succès!", Alert.AlertType.INFORMATION);
                resetForm();
                loadProducts();
            } else {
                showAlert("Erreur", "Impossible d'ajouter le produit", Alert.AlertType.ERROR);
            }
        } catch (SQLException e) {
            showAlert("Erreur", "Erreur de base de données: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    @FXML
    private void updateProduct() {
        if (selectedProduct == null) {
            showAlert("Attention", "Veuillez sélectionner un produit à modifier", Alert.AlertType.WARNING);
            return;
        }

        if (!validateForm()) return;

         try {
             Product product = createProductFromForm();
             product.setProductId(selectedProduct.getProductId());

             if (productService.update(product)) {
                showAlert("Succès", "Produit modifié avec succès!", Alert.AlertType.INFORMATION);
                resetForm();
                loadProducts();
            } else {
                showAlert("Erreur", "Impossible de modifier le produit", Alert.AlertType.ERROR);
            }
        } catch (SQLException e) {
            showAlert("Erreur", "Erreur de base de données: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

     @FXML
     private void editProduct() {
         selectedProduct = productTable.getSelectionModel().getSelectedItem();
         if (selectedProduct == null) {
             showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
             return;
         }

         loadProductToForm(selectedProduct);
     }

     /**
      * Charge les données du produit dans le formulaire
      */
     private void loadProductToForm(Product product) {
         if (product != null) {
             selectedProduct = product;
             nameField.setText(product.getName());
             descriptionField.setText(product.getDescription());
             priceField.setText(String.valueOf(product.getPrice()));
             stockField.setText(String.valueOf(product.getStockQty()));
             teamIdField.setText(String.valueOf(product.getTeamId()));
             skuField.setText(product.getSku());
             activeCheckBox.setSelected(product.isActive());
         }
     }

    @FXML
    private void deleteProduct() {
        Product product = productTable.getSelectionModel().getSelectedItem();
        if (product == null) {
            showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
            return;
        }

        Alert confirmAlert = new Alert(Alert.AlertType.CONFIRMATION);
        confirmAlert.setTitle("Confirmation");
        confirmAlert.setHeaderText("Supprimer le produit?");
        confirmAlert.setContentText("Êtes-vous sûr de vouloir supprimer: " + product.getName() + "?");

         Optional<ButtonType> result = confirmAlert.showAndWait();
         if (result.isPresent() && result.get() == ButtonType.OK) {
             try {
                 if (productService.delete(product.getProductId())) {
                    showAlert("Succès", "Produit supprimé!", Alert.AlertType.INFORMATION);
                    loadProducts();
                } else {
                    showAlert("Erreur", "Impossible de supprimer le produit", Alert.AlertType.ERROR);
                }
            } catch (SQLException e) {
                showAlert("Erreur", "Erreur de base de données: " + e.getMessage(), Alert.AlertType.ERROR);
            }
        }
    }

     @FXML
     private void resetForm() {
         nameField.clear();
         descriptionField.clear();
         priceField.clear();
         stockField.clear();
         teamIdField.clear();
         skuField.clear();
         activeCheckBox.setSelected(true);
         selectedProduct = null;
         productTable.getSelectionModel().clearSelection();
     }

    @FXML
    private void goToOrders() {
        navigateTo("OrderManagement.fxml");
    }

    @FXML
    private void goBack() {
        navigateTo("../Front/ListProducts.fxml");
    }

    private boolean validateForm() {
        String name = nameField.getText().trim();
        String priceText = priceField.getText().trim();
        String stockText = stockField.getText().trim();

        if (name.isEmpty()) {
            showAlert("Erreur", "Le nom du produit est obligatoire", Alert.AlertType.ERROR);
            return false;
        }

        try {
            double price = Double.parseDouble(priceText);
            int stock = Integer.parseInt(stockText);

            if (price < 0) {
                showAlert("Erreur", "Le prix doit être positif", Alert.AlertType.ERROR);
                return false;
            }
            if (stock < 0) {
                showAlert("Erreur", "Le stock doit être positif ou zéro", Alert.AlertType.ERROR);
                return false;
            }
            return true;
        } catch (NumberFormatException e) {
            showAlert("Erreur", "Prix et Stock doivent être des nombres", Alert.AlertType.ERROR);
            return false;
        }
    }

     private Product createProductFromForm() {
         Product product = new Product();
         product.setName(nameField.getText().trim());
         product.setDescription(descriptionField.getText().trim());
         product.setPrice(Double.parseDouble(priceField.getText().trim()));
         product.setStockQty(Integer.parseInt(stockField.getText().trim()));
         product.setTeamId(Integer.parseInt(teamIdField.getText().trim()));
         product.setSku(skuField.getText().trim());
         product.setActive(activeCheckBox.isSelected());
         return product;
     }

    private void navigateTo(String fxmlFile) {
        try {
            FXMLLoader loader;

            if (fxmlFile.startsWith("../Front/")) {
                // Navigation vers Front
                loader = new FXMLLoader(getClass().getResource("/fxml/Front/" + fxmlFile.replace("../Front/", "")));
            } else {
                // Navigation vers Admin
                loader = new FXMLLoader(getClass().getResource("/fxml/Admin/" + fxmlFile));
            }

            Parent root = loader.load();
            Scene scene = new Scene(root, 1200, 700);

            // Apply modern CSS stylesheet
            String styleSheet = getClass().getResource("/css/style_javafx.css").toExternalForm();
            scene.getStylesheets().add(styleSheet);

            Stage stage = (Stage) productTable.getScene().getWindow();
            stage.setScene(scene);
        } catch (IOException e) {
            showAlert("Erreur", "Impossible de charger la page: " + e.getMessage(), Alert.AlertType.ERROR);
            e.printStackTrace();
        }
    }

    private void showAlert(String title, String message, Alert.AlertType type) {
        Alert alert = new Alert(type);
        alert.setTitle(title);
        alert.setHeaderText(null);
        alert.setContentText(message);
        alert.showAndWait();
    }
}

