package org.example.model;

import java.util.ArrayList;
import java.util.List;

public class Cart {
    private int id;
    private int userId;
    private List<CartItem> items;

    // Constructors
    public Cart() {
        this.items = new ArrayList<>();
    }

    public Cart(int id, int userId) {
        this.id = id;
        this.userId = userId;
        this.items = new ArrayList<>();
    }

    public Cart(int id, int userId, List<CartItem> items) {
        this.id = id;
        this.userId = userId;
        this.items = items != null ? items : new ArrayList<>();
    }

    // Getters and Setters
    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public int getUserId() {
        return userId;
    }

    public void setUserId(int userId) {
        this.userId = userId;
    }

    public List<CartItem> getItems() {
        return items;
    }

    public void setItems(List<CartItem> items) {
        this.items = items;
    }

    public void addItem(CartItem item) {
        this.items.add(item);
    }

    public void removeItem(CartItem item) {
        this.items.remove(item);
    }

    public double getTotalPrice() {
        return items.stream().mapToDouble(CartItem::getTotalPrice).sum();
    }

    public int getTotalQuantity() {
        return items.stream().mapToInt(CartItem::getQuantity).sum();
    }

    public void clear() {
        this.items.clear();
    }

    @Override
    public String toString() {
        return "Cart{" +
                "id=" + id +
                ", userId=" + userId +
                ", items=" + items.size() +
                ", totalPrice=" + getTotalPrice() +
                '}';
    }
}

package org.example.model;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

public class Cart {
    private int cartId;
    private int userId;
    private String status; // OPEN | LOCKED | ORDERED
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;
    private LocalDateTime lockedAt;
    private List<CartItem> items;

    // Constructors
    public Cart() {
        this.items = new ArrayList<>();
        this.status = "OPEN";
    }

    public Cart(int cartId, int userId, String status) {
        this.cartId = cartId;
        this.userId = userId;
        this.status = status;
        this.items = new ArrayList<>();
    }

    public Cart(int cartId, int userId, String status, LocalDateTime createdAt, LocalDateTime updatedAt) {
        this.cartId = cartId;
        this.userId = userId;
        this.status = status;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
        this.items = new ArrayList<>();
    }

    public Cart(int userId, String status, List<CartItem> items) {
        this.userId = userId;
        this.status = status;
        this.items = items != null ? items : new ArrayList<>();
    }

    // Getters and Setters
    public int getCartId() {
        return cartId;
    }

    public void setCartId(int cartId) {
        this.cartId = cartId;
    }

    public int getUserId() {
        return userId;
    }

    public void setUserId(int userId) {
        this.userId = userId;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(LocalDateTime updatedAt) {
        this.updatedAt = updatedAt;
    }

    public LocalDateTime getLockedAt() {
        return lockedAt;
    }

    public void setLockedAt(LocalDateTime lockedAt) {
        this.lockedAt = lockedAt;
    }

    public List<CartItem> getItems() {
        return items;
    }

    public void setItems(List<CartItem> items) {
        this.items = items;
    }

    public void addItem(CartItem item) {
        this.items.add(item);
    }

    public void removeItem(CartItem item) {
        this.items.remove(item);
    }

    public double getTotalPrice() {
        return items.stream().mapToDouble(CartItem::getTotalPrice).sum();
    }

    public int getTotalQuantity() {
        return items.stream().mapToInt(CartItem::getQuantity).sum();
    }

    public void clear() {
        this.items.clear();
    }

    @Override
    public String toString() {
        return "Cart{" +
                "cartId=" + cartId +
                ", userId=" + userId +
                ", status='" + status + '\'' +
                ", items=" + items.size() +
                ", totalPrice=" + getTotalPrice() +
                '}';
    }
}

package org.example.controller;

import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.input.MouseEvent;
import javafx.stage.Stage;
import org.example.model.Product;
import org.example.service.ProductService;

import java.io.IOException;
import java.sql.SQLException;
import java.util.List;

public class ListProductsController {
    @FXML
    private TableView<Product> productTable;
    @FXML
    private TextField searchField;
    @FXML
    private ComboBox<String> filterCombo;

    private ProductService productService;
    private ObservableList<Product> productList;
    private int currentUserId = 1; // À récupérer de la session utilisateur

    @FXML
    public void initialize() {
        productService = new ProductService();
        loadProducts();
        setupFilterCombo();
    }

    private void loadProducts() {
        try {
            List<Product> products = productService.getAll();
            productList = FXCollections.observableArrayList(products);
            productTable.setItems(productList);
        } catch (SQLException e) {
            showAlert("Erreur", "Impossible de charger les produits: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    private void setupFilterCombo() {
        filterCombo.setItems(FXCollections.observableArrayList("Tous", "En stock", "En rupture"));
        filterCombo.setValue("Tous");
        filterCombo.setOnAction(e -> filterProducts());
    }

     @FXML
     private void filterProducts() {
         String searchText = searchField.getText().toLowerCase();
         String filterOption = filterCombo.getValue();

         ObservableList<Product> filteredList = FXCollections.observableArrayList();
         for (Product product : productList) {
             boolean matchesSearch = product.getName().toLowerCase().contains(searchText) ||
                     product.getDescription().toLowerCase().contains(searchText);

             boolean matchesFilter = filterOption.equals("Tous") ||
                     (filterOption.equals("En stock") && product.getStockQty() > 0) ||
                     (filterOption.equals("En rupture") && product.getStockQty() == 0);

             if (matchesSearch && matchesFilter) {
                 filteredList.add(product);
             }
         }
         productTable.setItems(filteredList);
     }

    @FXML
    private void showDetails() {
        Product selectedProduct = productTable.getSelectionModel().getSelectedItem();
        if (selectedProduct == null) {
            showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
            return;
        }
        navigateTo("ProductDetail.fxml", selectedProduct);
    }

     @FXML
     private void addToCart() {
         Product selectedProduct = productTable.getSelectionModel().getSelectedItem();
         if (selectedProduct == null) {
             showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
             return;
         }

         if (selectedProduct.getStockQty() <= 0) {
             showAlert("Erreur", "Ce produit est en rupture de stock", Alert.AlertType.ERROR);
             return;
         }

         TextInputDialog dialog = new TextInputDialog("1");
         dialog.setTitle("Ajouter au panier");
         dialog.setHeaderText("Quantité à ajouter");
         dialog.setContentText("Quantité:");

         dialog.showAndWait().ifPresent(quantity -> {
             try {
                 int qty = Integer.parseInt(quantity);
                 if (qty <= 0 || qty > selectedProduct.getStockQty()) {
                     showAlert("Erreur", "Quantité invalide", Alert.AlertType.ERROR);
                     return;
                 }
                 // Ajouter au panier (implémentation du service)
                 showAlert("Succès", selectedProduct.getName() + " ajouté au panier!", Alert.AlertType.INFORMATION);
             } catch (NumberFormatException e) {
                 showAlert("Erreur", "Quantité invalide", Alert.AlertType.ERROR);
             }
         });
     }

    @FXML
    private void goToCart() {
        navigateTo("Cart.fxml", null);
    }

    @FXML
    private void goToOrders() {
        navigateTo("Orders.fxml", null);
    }

    @FXML
    private void goToAdmin() {
        navigateTo("../Admin/CRUDProduct.fxml", null);
    }

    private void navigateTo(String fxmlFile, Object data) {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Front/" + fxmlFile));
            Parent root = loader.load();
            Scene scene = new Scene(root, 1200, 700);
            Stage stage = (Stage) productTable.getScene().getWindow();
            stage.setScene(scene);
            stage.setTitle("PiDeb - E-Sports Shop");
        } catch (IOException e) {
            showAlert("Erreur", "Impossible de charger la page: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    private void showAlert(String title, String message, Alert.AlertType type) {
        Alert alert = new Alert(type);
        alert.setTitle(title);
        alert.setHeaderText(null);
        alert.setContentText(message);
        alert.showAndWait();
    }
}

package org.example.controller;

import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.input.MouseEvent;
import javafx.stage.Stage;
import org.example.model.Product;
import org.example.service.ProductService;
import org.example.util.SceneUtils;

import java.io.IOException;
import java.sql.SQLException;
import java.util.List;

public class ListProductsController {
    @FXML
    private TableView<Product> productTable;
    @FXML
    private TextField searchField;
    @FXML
    private ComboBox<String> filterCombo;

    private ProductService productService;
    private ObservableList<Product> productList;
    private int currentUserId = 1; // À récupérer de la session utilisateur

    @FXML
    public void initialize() {
        productService = new ProductService();
        loadProducts();
        setupFilterCombo();
    }

    private void loadProducts() {
        try {
            List<Product> products = productService.getAll();
            productList = FXCollections.observableArrayList(products);
            productTable.setItems(productList);
        } catch (SQLException e) {
            showAlert("Erreur", "Impossible de charger les produits: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    private void setupFilterCombo() {
        filterCombo.setItems(FXCollections.observableArrayList("Tous", "En stock", "En rupture"));
        filterCombo.setValue("Tous");
        filterCombo.setOnAction(e -> filterProducts());
    }

     @FXML
     private void filterProducts() {
         String searchText = searchField.getText().toLowerCase();
         String filterOption = filterCombo.getValue();

         ObservableList<Product> filteredList = FXCollections.observableArrayList();
         for (Product product : productList) {
             boolean matchesSearch = product.getName().toLowerCase().contains(searchText) ||
                     product.getDescription().toLowerCase().contains(searchText);

             boolean matchesFilter = filterOption.equals("Tous") ||
                     (filterOption.equals("En stock") && product.getStockQty() > 0) ||
                     (filterOption.equals("En rupture") && product.getStockQty() == 0);

             if (matchesSearch && matchesFilter) {
                 filteredList.add(product);
             }
         }
         productTable.setItems(filteredList);
     }

    @FXML
    private void showDetails() {
        Product selectedProduct = productTable.getSelectionModel().getSelectedItem();
        if (selectedProduct == null) {
            showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
            return;
        }
        navigateTo("ProductDetail.fxml", selectedProduct);
    }

     @FXML
     private void addToCart() {
         Product selectedProduct = productTable.getSelectionModel().getSelectedItem();
         if (selectedProduct == null) {
             showAlert("Attention", "Veuillez sélectionner un produit", Alert.AlertType.WARNING);
             return;
         }

         if (selectedProduct.getStockQty() <= 0) {
             showAlert("Erreur", "Ce produit est en rupture de stock", Alert.AlertType.ERROR);
             return;
         }

         TextInputDialog dialog = new TextInputDialog("1");
         dialog.setTitle("Ajouter au panier");
         dialog.setHeaderText("Quantité à ajouter");
         dialog.setContentText("Quantité:");

         dialog.showAndWait().ifPresent(quantity -> {
             try {
                 int qty = Integer.parseInt(quantity);
                 if (qty <= 0 || qty > selectedProduct.getStockQty()) {
                     showAlert("Erreur", "Quantité invalide", Alert.AlertType.ERROR);
                     return;
                 }
                 // Ajouter au panier (implémentation du service)
                 showAlert("Succès", selectedProduct.getName() + " ajouté au panier!", Alert.AlertType.INFORMATION);
             } catch (NumberFormatException e) {
                 showAlert("Erreur", "Quantité invalide", Alert.AlertType.ERROR);
             }
         });
     }

    @FXML
    private void goToCart() {
        navigateTo("Cart.fxml", null);
    }

    @FXML
    private void goToOrders() {
        navigateTo("Orders.fxml", null);
    }

    @FXML
    private void goToAdmin() {
        navigateTo("../Admin/CRUDProduct.fxml", null);
    }

    private void navigateTo(String fxmlFile, Object data) {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Front/" + fxmlFile));
            Parent root = loader.load();
            Scene scene = new Scene(root, 1200, 700);
            Stage stage = (Stage) productTable.getScene().getWindow();
            stage.setScene(scene);
            stage.setTitle("PiDeb - E-Sports Shop");
        } catch (IOException e) {
            showAlert("Erreur", "Impossible de charger la page: " + e.getMessage(), Alert.AlertType.ERROR);
        }
    }

    private void showAlert(String title, String message, Alert.AlertType type) {
        Alert alert = new Alert(type);
        alert.setTitle(title);
        alert.setHeaderText(null);
        alert.setContentText(message);
        alert.showAndWait();
    }
}

package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;
import org.example.connection.MyConnection;

public class Main extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Charger le fichier FXML principal
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Front/ListProducts.fxml"));
        Parent root = loader.load();

        // Créer la scène
        Scene scene = new Scene(root, 1200, 700);

        // Charger les CSS globales (design moderne)
        String styleSheet = getClass().getResource("/css/styles.css").toExternalForm();
        scene.getStylesheets().add(styleSheet);

        // Configurer la fenêtre
        primaryStage.setTitle(" PiDeb - E-Sports Shop");
        primaryStage.setScene(scene);
        primaryStage.setWidth(1200);
        primaryStage.setHeight(700);
        primaryStage.setResizable(true);
        primaryStage.show();

        System.out.println("✓ Application PiDeb démarrée avec succès!");
        System.out.println("✓ CSS appliquées: " + styleSheet);
    }

    @Override
    public void stop() throws Exception {
        // Fermer la connexion à la base de données
        MyConnection.getInstance().close();
        super.stop();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

