/*
    JavaFX Style Bridge - Front Office (Pulse)
    Color Palette: #071422 (bg), #28ff8a (neon green)
*/

.root {
    /* Color Tokens */
    -fx-bg0: #071422;
    -fx-bg1: #0a1c2f;
    -fx-accent-green: #28ff8a;
    -fx-accent-cyan: #2bd2ff;
    -fx-accent-yellow: #ffd24a;

    -fx-glass: rgba(17, 48, 80, 0.45);
    -fx-glass-strong: rgba(10, 28, 47, 0.78);
    -fx-stroke: rgba(255, 255, 255, 0.12);
    -fx-text-main: #e9f2ff;
    -fx-text-muted: rgba(233, 242, 255, 0.65);

    -fx-background-color: linear-gradient(to bottom, -fx-bg0, -fx-bg1);
    -fx-font-family: "Space Grotesk", "Segoe UI", "system-ui";
    -fx-text-fill: -fx-text-main;
}

.label {
    -fx-text-fill: -fx-text-main;
}

.label-muted {
    -fx-text-fill: -fx-text-muted;
}

/* Header & Top Bar */
.hero-top {
    -fx-padding: 18px 22px;
}

.top-bar {
