}

.nav-item-active {
    -fx-background-color: rgba(40, 255, 138, 0.12);
    -fx-border-color: rgba(40, 255, 138, 0.25);
    -fx-text-fill: -fx-accent-green;
    -fx-border-radius: 18px;
    -fx-border-width: 1px;
}

/* Global Search */
.search-bar {
    -fx-background-color: rgba(17, 48, 80, 0.28);
    -fx-background-radius: 999px;
    -fx-border-radius: 999px;
    -fx-border-color: rgba(255, 255, 255, 0.14);
}

/* Buttons */
.button {
    -fx-background-color: -fx-glass;
    -fx-text-fill: -fx-text-main;
    -fx-background-radius: 999px;
    -fx-border-radius: 999px;
    -fx-border-color: -fx-stroke;
    -fx-padding: 12px 24px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
}

.button-green {
    -fx-background-color: linear-gradient(to bottom, #28ff8a, #1bd96f);
    -fx-text-fill: #04120a;
    -fx-border-color: rgba(40, 255, 138, 0.35);
}

.button-green:hover {
    -fx-effect: dropshadow(three-pass-box, rgba(40, 255, 138, 0.2), 20, 0, 0, 0);
}

.button-yellow {
    -fx-background-color: linear-gradient(to bottom, #ffd24a, #f5b025);
    -fx-text-fill: #1a1a1a;
}

/* TextAreas & TextFields */
.text-area, .text-field {
    -fx-background-color: rgba(255, 255, 255, 0.04);
    -fx-background-radius: 14px;
    -fx-border-radius: 14px;
    -fx-border-color: rgba(255, 255, 255, 0.12);
    -fx-text-fill: white;
    -fx-prompt-text-fill: rgba(255, 255, 255, 0.3);
    -fx-padding: 12px;
    -fx-transition: all 0.2s;
}

.text-area:focused, .text-field:focused {
    -fx-background-color: rgba(255, 255, 255, 0.06);
    -fx-border-color: -fx-accent-green;
    -fx-effect: dropshadow(three-pass-box, rgba(40, 255, 138, 0.1), 10, 0, 0, 0);
}

.text-area .content {
    -fx-background-color: transparent;
}

.text-area .scroll-pane {
    -fx-background-color: transparent;
}

